def solve(G, acc_col):
    Hg,Wg=len(G),len(G[0])
    A={(r,c) for r in range(Hg) for c in range(Wg) if G[r][c]==acc_col}
    # template = accent component offsets (single component assumed)
    comp=set(); stack=[next(iter(A))]
    while stack:
        r,c=stack.pop()
        if (r,c) in comp: continue
        comp.add((r,c))
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if (r+dr,c+dc) in A and (r+dr,c+dc) not in comp: stack.append((r+dr,c+dc))
    mr=min(r for r,c in comp); mc=min(c for r,c in comp)
    tmpl={(r-mr,c-mc) for r,c in comp}
    Z={(r,c) for r in range(Hg) for c in range(Wg) if G[r][c]==0}
    out=[row[:] for row in G]
    n=0
    for r in range(Hg):
        for c in range(Wg):
            P={(r+dr,c+dc) for dr,dc in tmpl}
            if all(0<=a<Hg and 0<=b<Wg for a,b in P) and P<=Z:
                n+=1
                for a,b in P: out[a][b]=acc_col
    return out,n
